<?php
declare(strict_types=1); namespace App\Http\Controllers\TeachingAssignments;use App\Http\Controllers\Controller;use App\Http\Requests\TeachingAssignments\SaveTeachingAssignmentRequest;use App\Models\{Classroom,Personnel,Subject,TeachingAssignment,TeachingAssignmentSet};use App\Services\TeachingAssignments\TeachingAssignmentService;use Illuminate\Http\RedirectResponse;use Illuminate\View\View;
class TeachingAssignmentController extends Controller {public function create():View{abort_unless(request()->user()->can('teaching-assignments.create'),403);return view('teaching-assignments.assignment-form',$this->options());}public function store(SaveTeachingAssignmentRequest $r,TeachingAssignmentService $s):RedirectResponse{$set=TeachingAssignmentSet::findOrFail($r->validated('assignment_set_id'));$s->save($r->user(),$set,$r->validated());return redirect()->route('teaching-assignments.index',['set'=>$set->id])->with('success','Penugasan berhasil ditambahkan.');}public function edit(TeachingAssignment $assignment):View{abort_unless(request()->user()->can('teaching-assignments.update'),403);return view('teaching-assignments.assignment-form',[...$this->options(),'assignment'=>$assignment]);}public function update(SaveTeachingAssignmentRequest $r,TeachingAssignment $assignment,TeachingAssignmentService $s):RedirectResponse{$set=$assignment->assignmentSet;$s->save($r->user(),$set,$r->validated(),$assignment);return redirect()->route('teaching-assignments.index',['set'=>$set->id]);}public function destroy(TeachingAssignment $assignment,TeachingAssignmentService $s):RedirectResponse{abort_unless(request()->user()->can('teaching-assignments.update'),403);$s->delete(request()->user(),$assignment);return back()->with('success','Penugasan dihapus dari draft.');}private function options():array{return ['sets'=>TeachingAssignmentSet::where('status','draft')->latest()->get(),'personnel'=>Personnel::where('is_active',true)->orderBy('full_name')->get(),'classrooms'=>Classroom::with('gradeLevel')->where('is_active',true)->get(),'subjects'=>Subject::where('is_active',true)->orderBy('sort_order')->get()];}}
